import pytest

from fees import late_fee


def test_on_time():
    assert late_fee(0, "standard") == 0.0
    assert late_fee(-2, "student") == 0.0


def test_standard():
    assert late_fee(4, "standard") == 1.0


def test_student_pays_half():
    assert late_fee(4, "student") == 0.5


def test_cap():
    assert late_fee(100, "standard") == 10.0


def test_unknown_member():
    with pytest.raises(ValueError):
        late_fee(3, "teacher")


