import pytest

from shop import apply_coupon, subtotal


def test_subtotal():
    assert subtotal({"pen": 2, "book": 1}) == 1599


def test_half():
    assert apply_coupon(1599, "HALF") == 799


def test_five():
    assert apply_coupon(1599, "FIVE") == 1099
    assert apply_coupon(300, "FIVE") == 0


def test_no_code():
    assert apply_coupon(1599, None) == 1599


def test_unknown_code():
    with pytest.raises(ValueError):
        apply_coupon(1599, "FREE")


def test_result_is_whole_cents():
    assert isinstance(apply_coupon(1599, "HALF"), int)


