from datetime import datetime


def format_date(d):
    """Return a date as 'Fri 25 Dec 2026'."""
    return d.strftime("%a %d %b %Y")


def days_until(date_text, today):
    """Days from `today` to the date in `date_text` (negative if it is in the past).

    Accepts "YYYY-MM-DD" and "DD/MM/YYYY"; anything else raises ValueError.
    """
    target = datetime.strptime(date_text, "%Y-%m-%d").date()
    return today - target
